@st.cache_resource
def load_program_model_components(models_dir='./models', data_dir='./prepared_data'):
    """
    Загружает компоненты для модели прогнозирования спроса на ПРОГРАММЫ.
    """
    components = {}
    try:
        # Загрузка модели
#        model_path = os.path.join(models_dir, 'model_demand_program.keras')  #для неоптимизированной модели
        model_path = os.path.join(models_dir, 'model_tuned_demand_program.keras')  #для оптимизированной модели
        if not os.path.exists(model_path):
            raise FileNotFoundError(f"Модель для программ не найдена: {model_path}")
        components['model'] = keras.models.load_model(model_path)

        # Загрузка скалера
        scaler_path = os.path.join(models_dir, "scaler_demand_program.pkl")
        if not os.path.exists(scaler_path):
            raise FileNotFoundError(f"Скалер для программ не найден: {scaler_path}")
        with open(scaler_path, 'rb') as f:
            components['scaler'] = pickle.load(f)

        # Загрузка кодировщика для университетов
        encoder_path = os.path.join('./data', 'university_label_encoder.pkl')
        if not os.path.exists(encoder_path):
            raise FileNotFoundError(f"Кодировщик для университетов не найден: {encoder_path}")
        components['university_encoder'] = joblib.load(encoder_path)

        st.success("Компоненты для модели программ успешно загружены.")
        return components
    except Exception as e:
        st.error(f"Критическая ошибка при загрузке компонентов модели программ: {e}")
        return None


@st.cache_resource  # Кэшируем ресурсы для быстрой загрузки
def load_prediction_components(models_dir='./models', data_dir='./prepared_data'):
    """
    Загружает модель, скалер и список признаков в ПРОСТОЙ СЛОВАРЬ.
    """
    components = {}
    try:
        # 1. Загрузка Keras модели
        model_path = os.path.join(models_dir, 'model_demand_university.keras')
        if not os.path.exists(model_path):
            raise FileNotFoundError(f"Модель не найдена: {model_path}")
        components['model'] = keras.models.load_model(model_path) # Ключ: 'model'

        # 2. Загрузка скалера и списка признаков из PKL файла
        data_path = os.path.join(models_dir, 'scaler_demand_university.pkl')
        if not os.path.exists(data_path):
            raise FileNotFoundError(f"Файл данных 'scaler_demand_university.pkl' не найден: {data_path}")
        with open(data_path, 'rb') as f:
            components['scaler'] = pickle.load(f)

        feature_path = os.path.join(models_dir, 'features_demand_university.pkl')
        if not os.path.exists(feature_path):
            raise FileNotFoundError(f"Признаки не найдены: {feature_path}")
        with open(feature_path, 'rb') as f:
            components['feature_names'] = pickle.load(f)


        st.success("Компоненты для прогнозирования успешно загружены.")
        return components

    except Exception as e:
        st.error(f"Критическая ошибка при загрузке компонентов: {e}")
        return None

def prepare_program_features(common_inputs_from_widgets, university_id, university_name, program_name, is_debug_target):
    """
    Создает полный словарь признаков для модели прогнозирования спроса на программу.

    Args:
        common_inputs_from_widgets (dict): Словарь с общими признаками из виджетов.
        university_id (int): ID выбранного университета.
        university_name (str): Название выбранного университета.
        program_name (str): Название выбранной программы.

    Returns:
        dict: Полный словарь признаков, готовый для predict_program_demand_streamlit.
    """
    # Задаем полный набор признаков со значениями по умолчанию ("заглушками")
    # Эти значения должны быть типичными "сырыми" значениями
    default_features =  {
        "year": 2025,
        "ege_change_prev_year": 0.25466421841606207,
        "cost_of_education_rub": 200.3236446825803,
        "gdp_per_capita_usd": 9.858285722886126,
        "gdp_usd_billion": 1.7783387014237981,
        "gdp_rub_billion": 30.091806387525963,
        "inflation_rate_percent": 5.8332717257156625,
        "mrot_rub": 13.324083862617018,
        "avg_salary_rub": 52.117248126185245,
        "real_salary_growth_percent": 4.467448300773607,
        "cpi_index": 200.4461184190723,
        "base_cpi": 100.4491857559977,
        "base_inflation_percent": 5.917807410974986,
        "gdp_deflator": 121.35555010384996,
        "population_million": 146.61882243159448,
        "unemployment_rate_percent": 4.536531109840162,
        }
    # 2. Начинаем с значений по умолчанию
    features = default_features.copy()

    # 3. Обновляем словарь значениями, которые ввел пользователь
    features.update(common_inputs_from_widgets)

    # 4. Добавляем информацию о вузе и программе
    features['university'] = university_id
    features['university_text'] = university_name
    features['selected_program'] = program_name  # Добавляем для использования внутри predict_...

    # 5. Добавляем one-hot encoded признаки для программ
    # Сначала все OHE-признаки равны 0
    all_program_columns = [f'program_group_{p}' for p_list in program_groups.values() for p in p_list]
    unique_program_columns = sorted(list(set(all_program_columns)))  # Уникальные и отсортированные

    for col in unique_program_columns:
        features[col] = 0

    # Устанавливаем 1 для выбранной программы
    selected_program_col = f"program_group_{program_name}"
    if selected_program_col in features:
        features[selected_program_col] = 1

    if is_debug_target:
        with st.expander(f"🕵️‍♂️ Отладка признаков для ВЫБРАННОЙ программы: '{program_name}'"):
            st.json(features)

    return features


def prepare_features_for_prediction(features_dict, deep_features, numeric_features, wide_feature, scaler=None):
    """
    Готовит признаки для ПЕРВОЙ модели (спрос на университет).
    """
    if scaler is None:
        print("ОШИБКА: Скейлер не передан в prepare_features_for_prediction.")
        return pd.DataFrame()

    # Задаем значения по умолчанию для первой модели
    default_features = {
        "year": 2025,
        "ege_change_prev_year": 0.25466421841606207,
        "cost_of_education_rub": 200.3236446825803,
        "gdp_per_capita_usd": 9.858285722886126,
        "gdp_usd_billion": 1.7783387014237981,
        "gdp_rub_billion": 30.091806387525963,
        "inflation_rate_percent": 5.8332717257156625,
        "mrot_rub": 13.324083862617018,
        "avg_salary_rub": 52.117248126185245,
        "real_salary_growth_percent": 4.467448300773607,
        "cpi_index": 200.4461184190723,
        "base_cpi": 100.4491857559977,
        "base_inflation_percent": 5.917807410974986,
        "gdp_deflator": 121.35555010384996,
        "population_million": 146.61882243159448,
        "unemployment_rate_percent": 4.536531109840162,
    }

    input_data = default_features.copy()
    input_data.update(features_dict)

    deep_df = pd.DataFrame([input_data])

    for feat in deep_features:
        if feat not in deep_df.columns:
            deep_df[feat] = 0
        if deep_df[feat].dtype == 'bool':
            deep_df[feat] = deep_df[feat].astype(int)

    deep_df[numeric_features] = scaler.transform(deep_df[numeric_features])
    deep_input_values = deep_df[deep_features].values.astype('float32')

    wide_input_value = np.array([[input_data.get(wide_feature, 0)]])

    prediction_inputs = {
        'deep_input': deep_input_values,
        'wide_input': wide_input_value
    }
    return prediction_inputs

def predict_program_demand_streamlit(user_inputs, program_components, is_debug_target):
    """
    Подготавливает данные и предсказывает спрос на программу (для Streamlit)
    """
    if not program_components:
        st.warning("Компоненты модели программ не загружены.")
        return 0.0

    # Извлекаем компоненты
    model = program_components['model']
    scaler = program_components['scaler']
    university_encoder = program_components['university_encoder']

    # 1. ПОДГОТОВКА ЧИСЛОВЫХ ПРИЗНАКОВ (numeric_input)

    numeric_features = [
        'year', 'avg_ege_paid', 'ege_change_prev_year',
        'cost_of_education_rub', 'avg_ege_budget',
        'gdp_per_capita_usd', 'gdp_usd_billion', 'gdp_rub_billion',
        'inflation_rate_percent', 'mrot_rub', 'avg_salary_rub',
        'real_salary_growth_percent', 'cpi_index', 'base_cpi',
        'base_inflation_percent', 'gdp_deflator', 'population_million',
        'unemployment_rate_percent'
    ]
    df_numeric = pd.DataFrame([user_inputs])
    for col in numeric_features:
        if col not in df_numeric.columns:
            df_numeric[col] = 0

    df_numeric = df_numeric[numeric_features]
    X_numeric_scaled = scaler.transform(df_numeric)

    # 2. ПОДГОТОВКА ПРИЗНАКОВ ПРОГРАММ (program_groups_input)

    # gолучаем форму входов из самой модели. Это список кортежей.
    # model.input_shape -> нужен второй элемент (индекс 1) и его вторая размерность (индекс 1).
    try:
        expected_program_features = model.input_shape[1][1]
    except (IndexError, TypeError):
        st.warning("Не удалось автоматически определить размерность программ. Используется значение по умолчанию (67).")
        expected_program_features = 67

    X_programs = np.zeros((1, expected_program_features))


    # Находим индекс выбранной программы в списке ВСЕХ возможных программ модели
    try:
        # понадобится полный список program_features, который использовался при обучении.
        # предположим, что он есть.
        # Мы предполагаем, что порядок в program_groups соответствует OHE.
        available_programs_for_uni = program_groups.get(user_inputs.get('university', 0), [])
        if user_inputs.get('selected_program') in available_programs_for_uni:
            prog_index = available_programs_for_uni.index(user_inputs.get('selected_program'))
            if prog_index < expected_program_features:
                X_programs[0, prog_index] = 1

    except (ValueError, IndexError):
        # Если что-то пошло не так, просто оставляем нулевой вектор
        pass

    # 3. ПОДГОТОВКА ID УНИВЕРСИТЕТА (university_input)
    university_name = user_inputs.get('university_text', '')
    try:
        if university_name and university_name in university_encoder.classes_:
            X_university = university_encoder.transform([university_name])
        else:
            X_university = np.array([0])
    except:
        X_university = np.array([0])

    if is_debug_target:
        with st.expander("Отладка входов в модель (для ВЫБРАННОЙ программы)"):
            st.write(f"**Форма `numeric_input`**: `{X_numeric_scaled.shape}`")
            st.write(f"**Форма `program_groups_input`**: `{X_programs.shape}`")
            st.write(f"**Форма `university_input`**: `{X_university.reshape(-1, 1).shape}`")
            st.write(f"**Значение `university_input`**: `{X_university[0]}` (для вуза: '{university_name}')")
            st.write(f"**Индекс активной программы**: `{np.argmax(X_programs) if np.sum(X_programs) > 0 else 'Нет'}`")

    # 4. ПРЕДСКАЗАНИЕ
    model_inputs = {
        'numeric_input': X_numeric_scaled,
        'program_groups_input': X_programs,
        'university_input': X_university.reshape(-1, 1)
    }

    try:
        prediction = model.predict(model_inputs, verbose=0)[0, 0]
        print(f"Program predict :{prediction}")
        return max(0.0, float(prediction))
    except Exception as e:
        st.error(f"Ошибка при предсказании спроса на программу: {e}")
        return 0.0


def predict_demand_share(user_inputs, components):
    """
    Предсказывает ДОЛЮ спроса, используя компоненты из ПРОСТОГО СЛОВАРЯ.
    """
    # проверка наличия всех компонентов
    if not all(k in components for k in ['model', 'scaler', 'feature_names']):
        st.error("Компоненты модели загружены некорректно или отсутствуют.")
        st.write("Содержимое 'components':", components)  # Для отладки
        return 0.0



    # Прямое извлечение
    model = components['model']
    feature_names = components['feature_names']
    d_features = feature_names['deep_features_list']
    n_features = feature_names['numeric_features_deep']
    w_feature = feature_names['wide_feature']
    scaler = components['scaler']


    try:
        # Подготовка полного набора признаков
        features_prepared = prepare_features_for_prediction(user_inputs, d_features, n_features, w_feature, scaler)

        # Предсказание
        prediction = model.predict(features_prepared, verbose=0)[0, 0]

        return max(0.0, min(1.0, float(prediction)))
    except Exception as e:
        st.error(f"Ошибка во время предсказания: {e}")
        return 0.0


