# ЗАГРУЗКА КОМПОНЕНТОВ ДЛЯ ОБЕИХ МОДЕЛЕЙ
# Модель 1: Спрос на университет
prediction_components = load_prediction_components()

# Модель 2: Спрос на программу
prog_prediction_components = load_program_model_components()
# БОКОВАЯ ПАНЕЛЬ
with st.sidebar:
    st.image(
        "https://lomonosov-msu.ru/media/cache/event_logo/file/event/8714/rus_logo_e69966316674c7035e14f995352b4b6eccb36f86.png",
        width=250)
    st.header("Параметры прогноза")

    selected_university_name = st.selectbox("Наименование ВУЗа:", options=list(universities.values()), index=1)


    selected_university_index = None
    for index, name in universities.items():
        if name == selected_university_name:
            selected_university_index = index
            break

    available_programs = program_groups.get(selected_university_index, [])
    selected_program = st.selectbox("Направление обучения:", options=available_programs)

    year = st.slider("Год прогноза:", 2024, 2030, 2026)
    predicted_cost_thousands = st.number_input("Прогнозная стоимость (тыс. руб./год):", min_value=100, max_value=800,
                                               value=250, step=10)
    avg_ege_p = st.number_input("Средний балл ЕГЭ на платное направление:", min_value=50.00, max_value=100.00, value=70.00, step=0.10)
    avg_ege_b = st.number_input("Средний балл ЕГЭ на бюджтное направление:", min_value=50.00, max_value=100.00, value=85.00, step=0.10)

    with st.expander("Экономические показатели"):
        mrot_thousands = st.number_input("МРОТ (тыс. руб.):", value=22.0, step=0.5)
        avg_salary_thousands = st.number_input("Средняя зарплата (тыс. руб.):", value=85.0, step=1.0)
        cpi_index = st.slider("Индекс потр. цен:", 100.0, 300.0, 200.0, 0.1)  # Как в демо
        inflation_rate_percent = st.slider("Уровень инфляции (%):", 1.0, 20.0, 7.0, 0.1)

    predict_button = st.button("🚀 Запустить прогноз", type="primary", use_container_width=True)

# ОСНОВНАЯ ОБЛАСТЬ
if not predict_button:
    st.info("Задайте параметры в боковой панели и нажмите 'Запустить прогноз'")
    st.stop()

with st.spinner('Выполняется комплексное прогнозирование...'):
    # --------------------------------------------------------------------------
    # 1. ПРОГНОЗ ПО ВСЕМ УНИВЕРСИТЕТАМ
    # --------------------------------------------------------------------------

    common_features = {
        "year": year, "cost_of_education_rub": predicted_cost_thousands,
        "mrot_rub": mrot_thousands, "avg_salary_rub": avg_salary_thousands,
        "cpi_index": cpi_index, "inflation_rate_percent": inflation_rate_percent,
        "avg_ege_paid": avg_ege_p, "avg_ege_budget": avg_ege_b
    }
    st.write("Выполняется прогноз для каждого университета...")
    all_demands_dict = {}
    TOTAL_MARKET_SIZE = 450000
    progress_bar = st.progress(0)
    for i, (uni_id, uni_name) in enumerate(universities.items()):
        features_for_this_uni = common_features.copy()
        features_for_this_uni['university'] = uni_id
        predicted_share = predict_demand_share(features_for_this_uni, prediction_components)
        all_demands_dict[uni_name] = int(predicted_share * TOTAL_MARKET_SIZE)
        progress_bar.progress((i + 1) / len(universities))
    progress_bar.empty()
    st.success("Прогноз по всем университетам завершен!")

    # Сохраняем оригинальный прогноз для выбранного вуза
    predicted_demand_uni = all_demands_dict.get(selected_university_name, 0)

    # --------------------------------------------------------------------------
    # 2. ПРОГНОЗ ПО ВСЕМ ПРОГРАММАМ ВЫБРАННОГО УНИВЕРСИТЕТА
    # --------------------------------------------------------------------------
    all_program_demands_dict = {}

    if available_programs and prog_prediction_components:
        st.write(
            f"Выполняется детальный прогноз для {len(available_programs)} программ в {selected_university_name}...")

        common_prog_features = common_features.copy()  # Используем те же общие фичи

        for i, prog_name in enumerate(available_programs):
            #is_debug_target = (prog_name == selected_program)
            is_debug_target = False
            features_for_this_prog = prepare_program_features(
                common_inputs_from_widgets=common_prog_features,
                university_id=selected_university_index,
                university_name=selected_university_name,
                program_name=prog_name,
                is_debug_target=is_debug_target
            )
            predicted_share_prog = predict_program_demand_streamlit(
                features_for_this_prog, prog_prediction_components, is_debug_target
            )
            # считаем долю от оригинального прогноза по вузу
            absolute_demand_prog = int(predicted_share_prog * predicted_demand_uni)
            all_program_demands_dict[prog_name] = absolute_demand_prog

    # --------------------------------------------------------------------------
    # 3. ПОДГОТОВКА ДАННЫХ ДЛЯ ВИЗУАЛИЗАЦИИ
    # --------------------------------------------------------------------------
    # Прогноз для выбранной программы
    predicted_demand_prog = all_program_demands_dict.get(selected_program, 0)
    # Сумма по программам для отображения
    sum_of_all_programs = sum(all_program_demands_dict.values())
    # Переменная для отображения итогового числа в вузе
    display_demand_uni = sum_of_all_programs if sum_of_all_programs > 0 else predicted_demand_uni

# ==============================================================================
# ВИЗУАЛИЗАЦИЯ
# ==============================================================================

# Заголовок
st.markdown(
    f'<div class="result-header"><h2>{selected_university_name}</h2><h4>Направление обучения - {selected_program}</h4><h3>Прогноз на {year} г.</h3></div>',
    unsafe_allow_html=True)
st.markdown("---")

# --------------------------------------------------------------------------
# БЛОК 1: УРОВЕНЬ СПРОСА СРЕДИ ДРУГИХ ВУЗОВ
# --------------------------------------------------------------------------
st.markdown('<p class="section-title-uni">Уровень спроса среди других ВУЗов</p>', unsafe_allow_html=True)
col1, col2 = st.columns([2, 3])

with col1:
    # Процент считаем от ОРИГИНАЛЬНОГО прогноза
    percentage_uni = (predicted_demand_uni / TOTAL_MARKET_SIZE) * 100 if TOTAL_MARKET_SIZE > 0 else 0
    fig_gauge_uni = go.Figure(
        go.Indicator(mode="gauge+number", value=percentage_uni, number={'suffix': '%', 'font': {'size': 48}},
                     gauge={'shape': "angular", 'axis': {'range': [None, 10]}, 'bar': {'color': "#dc2626"}}))
    # Число показываем СУММАРНОЕ
    fig_gauge_uni.update_layout(height=250, margin=dict(l=20, r=20, t=60, b=20), title={
        'text': f"Общее количество<br>поступивших в ВУЗ: <b>{display_demand_uni:,}</b>", 'y': 0.95, 'x': 0.5,
        'xanchor': 'center', 'yanchor': 'top'})
    st.plotly_chart(fig_gauge_uni, use_container_width=True)
with col2:

    # 1. Берем прогнозы и сортируем всех по убыванию
    uni_demand_pairs = sorted(all_demands_dict.items(), key=lambda item: item[1], reverse=True)

    # 2. Находим индекс (позицию в рейтинге) нашего выбранного университета
    try:
        selected_uni_index = \
        [i for i, (name, demand) in enumerate(uni_demand_pairs) if name == selected_university_name][0]
    except IndexError:
        print("ERROR index not found")
        # Если вуз не найден  просто показываем топ-10
        final_chart_data = uni_demand_pairs[:10]
    else:

        # Определяем срезы для конкурентов "до" и "после"
        start_index = max(0, selected_uni_index - 5)
        end_index = min(len(uni_demand_pairs), selected_uni_index + 5)  # +4 вуза после и +1 наш

        # Формируем итоговый список для графика
        final_chart_data = uni_demand_pairs[start_index:end_index]

    # 4. Сортируем итоговый список для красивого отображения на графике (от меньшего к большему)
    final_chart_data.sort(key=lambda item: item[1])


    if final_chart_data:
        chart_universities, chart_demands = zip(*final_chart_data)

        colors = ['#dc2626' if univ == selected_university_name else '#6b7280' for univ in chart_universities]

        fig_bar_uni = go.Figure(go.Bar(x=chart_demands, y=chart_universities, orientation='h', marker_color=colors))
        fig_bar_uni.update_layout(
            title="Сравнение с ближайшими конкурентами",
            xaxis_title="Кол-во абитуриентов (прогноз)",
            yaxis_title="",
            height=350,
            margin=dict(l=10, r=10, t=30, b=10),
            showlegend=False,
            xaxis=dict(showticklabels=False)
        )
        st.plotly_chart(fig_bar_uni, use_container_width=True)
    else:
        st.write("Нет данных для сравнения.")

# --------------------------------------------------------------------------
# БЛОК 2: УРОВЕНЬ СПРОСА НА НАПРАВЛЕНИЕ ВНУТРИ ВУЗА
# --------------------------------------------------------------------------
st.markdown('<p class="section-title-prog">Уровень спроса на направление внутри ВУЗа</p>', unsafe_allow_html=True)
col3, col4 = st.columns([2, 3])

with col3:
    # Процент для программы считаем относительно СУММЫ по программам
    percentage_prog = (predicted_demand_prog / sum_of_all_programs) * 100 if sum_of_all_programs > 0 else 0
    fig_gauge_prog = go.Figure(
        go.Indicator(mode="gauge+number", value=percentage_prog, number={'suffix': '%', 'font': {'size': 48}},
                     gauge={'shape': "angular", 'axis': {'range': [None, 30]}, 'bar': {'color': "#1e3a8a"}}))
    fig_gauge_prog.update_layout(height=250, margin=dict(l=20, r=20, t=60, b=20),
                                 title={'text': f"Прогноз спроса<br>на направление: <b>{predicted_demand_prog:,}</b>",
                                        'y': 0.95, 'x': 0.5, 'xanchor': 'center', 'yanchor': 'top'})
    st.plotly_chart(fig_gauge_prog, use_container_width=True)

with col4:
    if all_program_demands_dict:
        # Этот код уже готовит правильные данные
        prog_demand_pairs = list(all_program_demands_dict.items())
        prog_demand_pairs.sort(key=lambda item: item[1], reverse=True)
        selected_prog_data = (selected_program, predicted_demand_prog)
        top_prog_competitors = [item for item in prog_demand_pairs if item[0] != selected_program][:9]
        final_prog_chart_data = [selected_prog_data] + top_prog_competitors
        final_prog_chart_data.sort(key=lambda item: item[1])
        chart_programs, chart_program_demands = zip(*final_prog_chart_data)

        colors_prog = ['#1e3a8a' if prog == selected_program else '#6b7280' for prog in chart_programs]

        fig_bar_prog = go.Figure(
            go.Bar(
                x=chart_program_demands,
                y=chart_programs,
                orientation='h',
                marker_color=colors_prog,
                text=chart_program_demands,  # <-- Возвращаем этот параметр
                textposition='auto',  # <-- Позиция текста (auto обычно хорошо работает)
                textfont=dict(color='rgba(0, 0, 0, 0.8)')  # <-- Цвет текста для лучшей читаемости
            )
        )


        fig_bar_prog.update_layout(
            title="Сравнение с топ-направлениями в ВУЗе",
            xaxis_title="Кол-во абитуриентов",
            yaxis_title="",
            height=350,
            margin=dict(l=10, r=10, t=30, b=10),  # Уменьшаем отступы для компактности
            showlegend=False
        )
        st.plotly_chart(fig_bar_prog, use_container_width=True)
    else:
        st.write("Прогнозы по программам для данного ВУЗа не отображаются.")
